import{_ as e,c as t,o,a2 as a}from"./chunks/framework.DdOM6S6U.js";const y=JSON.parse('{"title":"Remote API Core Classes","description":"","frontmatter":{"sidebarPos":4,"sidebarTitle":"Core Classes","outline":"deep"},"headers":[],"relativePath":"guide/remote-api/core-classes.md","filePath":"guide/remote-api/core-classes.md","lastUpdated":1785606393000}'),r={name:"guide/remote-api/core-classes.md"},d=a('<h1 id="remote-api-core-classes" tabindex="-1">Remote API Core Classes <a class="header-anchor" href="#remote-api-core-classes" aria-label="Permalink to &quot;Remote API Core Classes&quot;">​</a></h1><p>Reference for the main PHP classes in <code>src/Services/RemoteApi/</code>, traits, and the admin hydrate.</p><h2 id="model-repository-traits" tabindex="-1">Model &amp; Repository Traits <a class="header-anchor" href="#model-repository-traits" aria-label="Permalink to &quot;Model &amp; Repository Traits&quot;">​</a></h2><h3 id="hasremoteapisource-src-entities-traits-hasremoteapisource-php" tabindex="-1"><code>HasRemoteApiSource</code> (<code>src/Entities/Traits/HasRemoteApiSource.php</code>) <a class="header-anchor" href="#hasremoteapisource-src-entities-traits-hasremoteapisource-php" aria-label="Permalink to &quot;`HasRemoteApiSource` (`src/Entities/Traits/HasRemoteApiSource.php`)&quot;">​</a></h3><table><thead><tr><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>remoteApiSource()</code></td><td><code>MorphOne</code> to <code>RemoteApiSource</code></td></tr><tr><td><code>getRemoteApiId()</code></td><td>Current remote id (virtual or persisted)</td></tr><tr><td><code>hydrateRemoteApiAttributes()</code></td><td>Load synced fields onto the model</td></tr><tr><td><code>persistRemoteApiVirtualAttributes()</code></td><td>Write virtual dirty fields to side table</td></tr><tr><td><code>stripRemoteApiVirtualAttributes()</code></td><td>Remove virtual keys before parent save</td></tr><tr><td><code>toRemoteApiArray()</code></td><td>Merged array for API transformers</td></tr></tbody></table><p>Bootstraps <code>RemoteApiSourceableObserver</code>.</p><h3 id="remoteapisourcetrait-src-repositories-traits-remoteapisourcetrait-php" tabindex="-1"><code>RemoteApiSourceTrait</code> (<code>src/Repositories/Traits/RemoteApiSourceTrait.php</code>) <a class="header-anchor" href="#remoteapisourcetrait-src-repositories-traits-remoteapisourcetrait-php" aria-label="Permalink to &quot;`RemoteApiSourceTrait` (`src/Repositories/Traits/RemoteApiSourceTrait.php`)&quot;">​</a></h3><p>Repository entry point. Requires <code>Moduleable</code> for module/route resolution.</p><table><thead><tr><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>remoteApiConnector()</code></td><td>Resolve connector via <code>RemoteApiConnectorFactory</code></td></tr><tr><td><code>syncFromRemote($localId, $remoteId)</code></td><td>Single-record sync</td></tr><tr><td><code>syncAllFromRemote()</code></td><td>List-first batch sync</td></tr><tr><td><code>previewSyncFromRemote()</code> / <code>previewSyncAllFromRemote()</code></td><td>Dry-run summaries (no HTTP)</td></tr><tr><td><code>previewRemoteCatalog($catalogKey)</code></td><td>Catalog fetch preview</td></tr><tr><td><code>clearRemoteApiCache($remoteId)</code></td><td>Flush connector cache</td></tr><tr><td><code>listRemoteCatalog($catalogKey)</code></td><td>Paginated catalog rows (cached)</td></tr><tr><td><code>previewRemote($remoteId)</code></td><td>Fetch one row through cache</td></tr><tr><td><code>getRemoteApiActionSchema()</code></td><td>Table/row action definitions from <code>actions</code> config</td></tr></tbody></table><h2 id="controller-trait" tabindex="-1">Controller Trait <a class="header-anchor" href="#controller-trait" aria-label="Permalink to &quot;Controller Trait&quot;">​</a></h2><h3 id="manageremoteapisync-src-http-controllers-traits-manageremoteapisync-php" tabindex="-1"><code>ManageRemoteApiSync</code> (<code>src/Http/Controllers/Traits/ManageRemoteApiSync.php</code>) <a class="header-anchor" href="#manageremoteapisync-src-http-controllers-traits-manageremoteapisync-php" aria-label="Permalink to &quot;`ManageRemoteApiSync` (`src/Http/Controllers/Traits/ManageRemoteApiSync.php`)&quot;">​</a></h3><p>Included on <code>BaseController</code>. Registers table toolbar actions when the repository uses <code>RemoteApiSourceTrait</code> and the connector is enabled.</p><table><thead><tr><th>HTTP action</th><th>Method</th><th>Route pattern</th></tr></thead><tbody><tr><td>Sync one record</td><td><code>syncRemote</code></td><td><code>PUT …/sync-remote/{id}</code></td></tr><tr><td>Sync all linked</td><td><code>syncRemoteAll</code></td><td><code>POST …/sync-remote-all</code></td></tr><tr><td>Clear cache</td><td><code>clearRemoteCache</code></td><td><code>POST …/clear-remote-cache</code></td></tr><tr><td>Preview payload</td><td><code>previewRemote</code></td><td><code>PUT …/preview-remote/{id}</code></td></tr><tr><td>Catalog list (combobox)</td><td><code>listRemoteCatalog</code></td><td><code>GET …/list-remote-catalog</code></td></tr></tbody></table><p><code>RemoteApiSyncException</code> is converted to <code>ValidationException</code> on the <code>remote_api</code> key for frontend error display.</p><p><code>setTableActionsManageRemoteApiSync()</code> merges <code>syncRemoteAll</code> and <code>clearRemoteCache</code> (scope <code>table</code>) into <code>$this-&gt;tableActions</code>.</p><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><h3 id="remoteapisynchronizer" tabindex="-1"><code>RemoteApiSynchronizer</code> <a class="header-anchor" href="#remoteapisynchronizer" aria-label="Permalink to &quot;`RemoteApiSynchronizer`&quot;">​</a></h3><p>Orchestrates create/update logic:</p><ul><li><strong><code>syncRecord($connector, $repository, $remoteId)</code></strong> — <code>fetchOne(..., forceRefresh: true)</code> → map → partition → repository create/update → sync <code>RemoteApiSource</code>.</li><li><strong><code>syncAll($connector, $repository)</code></strong> — Stream remote list pages (<code>eachListPage</code> + forceRefresh) → update linked locals → optionally import new remote ids → <code>clearCache()</code> → return stats + skipped stale links + HTTP request counts.</li><li><strong><code>previewSyncRecord</code> / <code>previewSyncAll</code></strong> — Configuration summary without HTTP or DB writes.</li></ul><p>Throws <code>RemoteApiSyncException</code> when a single-record fetch returns null.</p><h3 id="remoteapiclient" tabindex="-1"><code>RemoteApiClient</code> <a class="header-anchor" href="#remoteapiclient" aria-label="Permalink to &quot;`RemoteApiClient`&quot;">​</a></h3><p>Low-level HTTP via Laravel <code>Http</code> facade:</p><ul><li><strong><code>get($endpoint, $query, $allowNotFound)</code></strong> — Asserts rate limit, records request, handles 404/429.</li><li><strong><code>eachPaginatedListPage</code></strong> — Streams pages via callback (no full-list accumulation); validates complete fetch; max 100 pages safety cap.</li><li><strong><code>fetchPaginatedListResult</code></strong> — Collects all pages from <code>eachPaginatedListPage</code> into <code>{ items, expected_total }</code>.</li><li><strong><code>getItem</code></strong> — Extracts single item via <code>item_path</code>.</li><li>Merges <code>http.includes</code> as <code>include=</code> query param unless <code>_skip_sync_includes</code> is set (catalog fetches).</li></ul><p>Uses <code>RemoteApiRateLimiter</code> before each request and <code>RemoteApiRequestTracker</code> after.</p><h3 id="remoteapicache" tabindex="-1"><code>RemoteApiCache</code> <a class="header-anchor" href="#remoteapicache" aria-label="Permalink to &quot;`RemoteApiCache`&quot;">​</a></h3><table><thead><tr><th>Method</th><th>Behavior</th></tr></thead><tbody><tr><td><code>remember($key, $callback)</code></td><td>Standard TTL cache</td></tr><tr><td><code>rememberNonEmpty($key, $callback)</code></td><td>Skips caching empty arrays</td></tr><tr><td><code>rememberPaginatedCatalog($key, $callback)</code></td><td>Stores <code>{ expected_total, items }</code>; validates on read</td></tr><tr><td><code>forget($key)</code></td><td>Drop one key</td></tr><tr><td><code>flush($remoteId)</code></td><td>Per-record keys or full tag/version flush</td></tr></tbody></table><p>Cache key format:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>remote-api:{module_snake}:{route_snake}:{version}:{key}</span></span></code></pre></div><p>Tag format (when store supports tags): <code>remote-api.{module}.{route}</code> from <code>RemoteApiConfiguration::cacheTag()</code>.</p><p>Without tags, <code>flush(null)</code> bumps a version key so prefixed keys effectively invalidate.</p><h3 id="remoteapiratelimiter" tabindex="-1"><code>RemoteApiRateLimiter</code> <a class="header-anchor" href="#remoteapiratelimiter" aria-label="Permalink to &quot;`RemoteApiRateLimiter`&quot;">​</a></h3><p>Outgoing client guard using Laravel <code>RateLimiter</code>:</p><ul><li>Keys: <code>remote-api-outgoing:{host}:{path-without-trailing-id}</code> + <code>:minute</code> / <code>:hour</code> suffixes.</li><li><strong><code>assertCanRequest($url)</code></strong> — Throws <code>RemoteApiSyncException::rateLimitExceeded()</code> when over limit.</li><li><strong><code>hit($url)</code></strong> — Increments counters (60s / 3600s decay).</li></ul><p>Also surfaces remote <strong>429</strong> responses from <code>RemoteApiClient::get()</code> as <code>RemoteApiSyncException</code> with <code>Retry-After</code>.</p><h3 id="remoteapirequesttracker" tabindex="-1"><code>RemoteApiRequestTracker</code> <a class="header-anchor" href="#remoteapirequesttracker" aria-label="Permalink to &quot;`RemoteApiRequestTracker`&quot;">​</a></h3><p>In-memory per-connector request stats:</p><ul><li><strong><code>record($url)</code></strong> — Normalizes URL (scheme + host + path, strips query).</li><li><strong><code>flush()</code></strong> — Returns <code>{ total, by_url }</code> and resets.</li></ul><p>Used by <code>syncAll()</code> response meta and connector <code>flushRequestStats()</code>.</p><h3 id="remoteapiconnectorfactory" tabindex="-1"><code>RemoteApiConnectorFactory</code> <a class="header-anchor" href="#remoteapiconnectorfactory" aria-label="Permalink to &quot;`RemoteApiConnectorFactory`&quot;">​</a></h3><p>Builds a wired connector:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">RemoteApiConnectorFactory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ModuleName&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;entity_name&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → new EntityNameRemoteApiConnector($configuration, $client, $cache, $adapter)</span></span></code></pre></div><p>Shares one package-level <code>RemoteApiRateLimiter</code> instance across connectors.</p><h3 id="remoteapiconnectorresolver" tabindex="-1"><code>RemoteApiConnectorResolver</code> <a class="header-anchor" href="#remoteapiconnectorresolver" aria-label="Permalink to &quot;`RemoteApiConnectorResolver`&quot;">​</a></h3><p>Resolves <code>RemoteApiConfiguration</code>, connector/adapter/DTO class names from module route config or connector static config.</p><h3 id="remoteapiconfiguration" tabindex="-1"><code>RemoteApiConfiguration</code> <a class="header-anchor" href="#remoteapiconfiguration" aria-label="Permalink to &quot;`RemoteApiConfiguration`&quot;">​</a></h3><p>Typed accessor for all connector settings: URLs, paths, mapping, cache, catalogs, actions, <code>toSummaryArray()</code> for previews.</p><p>Factory methods:</p><ul><li><code>fromConnectorClass($module, $routeName, $connectorClass)</code></li><li><code>fromRouteConfig($module, $routeName, $config)</code></li></ul><h3 id="abstractremoteapiconnector" tabindex="-1"><code>AbstractRemoteApiConnector</code> <a class="header-anchor" href="#abstractremoteapiconnector" aria-label="Permalink to &quot;`AbstractRemoteApiConnector`&quot;">​</a></h3><p>Default fetch/cache pipeline:</p><table><thead><tr><th>Method</th><th>Cache key</th><th>Notes</th></tr></thead><tbody><tr><td><code>fetchList($query, $forceRefresh)</code></td><td><code>list:v2:{md5(query)}</code></td><td>Paginated list via <code>rememberPaginatedCatalog</code></td></tr><tr><td><code>eachListPage($callback, $query, $forceRefresh)</code></td><td>—</td><td>Streams pages; forceRefresh skips list cache</td></tr><tr><td><code>fetchOne($id, $query, $forceRefresh)</code></td><td><code>record:{id}</code></td><td>Single item; forceRefresh bypasses cache read</td></tr><tr><td><code>listCatalog($key)</code></td><td><code>catalog:v2:…</code></td><td>Default list or named catalog endpoint</td></tr><tr><td><code>clearCache($id)</code></td><td>—</td><td>Delegates to <code>RemoteApiCache::flush</code></td></tr></tbody></table><p>Override hooks: <code>beforeFetch</code>, <code>afterFetch</code>, <code>afterFetchOne</code>, <code>beforeCatalogFetch</code>.</p><h3 id="abstractremoteapiadapter-remoteapifieldmapper" tabindex="-1"><code>AbstractRemoteApiAdapter</code> / <code>RemoteApiFieldMapper</code> <a class="header-anchor" href="#abstractremoteapiadapter-remoteapifieldmapper" aria-label="Permalink to &quot;`AbstractRemoteApiAdapter` / `RemoteApiFieldMapper`&quot;">​</a></h3><p><code>mapToAttributes($row, $existingAttributes)</code> applies config <code>mapping</code>, field rules, and optional <code>afterMap</code> / <code>transformField</code> overrides in module adapters.</p><h3 id="remoteapiattributepartition" tabindex="-1"><code>RemoteApiAttributePartition</code> <a class="header-anchor" href="#remoteapiattributepartition" aria-label="Permalink to &quot;`RemoteApiAttributePartition`&quot;">​</a></h3><p>Splits mapped attributes into local entity fillable vs remote side-table payload (see <a href="./database">Database</a>).</p><h2 id="hydrate-input" tabindex="-1">Hydrate Input <a class="header-anchor" href="#hydrate-input" aria-label="Permalink to &quot;Hydrate Input&quot;">​</a></h2><h3 id="remoteapihydrate-src-hydrates-inputs-remoteapihydrate-php" tabindex="-1"><code>RemoteApiHydrate</code> (<code>src/Hydrates/Inputs/RemoteApiHydrate.php</code>) <a class="header-anchor" href="#remoteapihydrate-src-hydrates-inputs-remoteapihydrate-php" aria-label="Permalink to &quot;`RemoteApiHydrate` (`src/Hydrates/Inputs/RemoteApiHydrate.php`)&quot;">​</a></h3><table><thead><tr><th>Config type</th><th>Hydrated schema type</th><th>Vue component</th></tr></thead><tbody><tr><td><code>remote-api</code></td><td><code>input-remote-api</code></td><td><code>VInputRemoteApi</code> (<code>vue/src/js/components/inputs/RemoteApi.vue</code>)</td></tr></tbody></table><p>Hydrate behavior:</p><ul><li>Sets <code>name</code> default to <code>remote_id</code>.</li><li>Loads catalog items via <code>listRemoteCatalog()</code> when not in console.</li><li>Exposes <code>catalogEndpoint</code> for frontend async refresh.</li><li>Resolves <code>itemValue</code> from mapping (<code>remote_id</code> → remote JSON id key).</li></ul><p>Registry: <code>&#39;input-remote-api&#39;: &#39;VInputRemoteApi&#39;</code> in <code>vue/src/js/components/inputs/registry.js</code>.</p><h2 id="observers" tabindex="-1">Observers <a class="header-anchor" href="#observers" aria-label="Permalink to &quot;Observers&quot;">​</a></h2><table><thead><tr><th>Observer</th><th>Trigger</th><th>Effect</th></tr></thead><tbody><tr><td><code>RemoteApiSourceableObserver</code></td><td>Entity retrieved/saving/saved/forceDeleting</td><td>Virtual attribute lifecycle</td></tr><tr><td><code>RemoteApiSourceObserver</code></td><td><code>RemoteApiSource</code> saved</td><td><code>touchQuietly()</code> parent</td></tr></tbody></table><h2 id="exceptions" tabindex="-1">Exceptions <a class="header-anchor" href="#exceptions" aria-label="Permalink to &quot;Exceptions&quot;">​</a></h2><table><thead><tr><th>Class</th><th>When</th></tr></thead><tbody><tr><td><code>RemoteApiConfigurationException</code></td><td>Missing base URL, endpoint, disabled connector, invalid catalog</td></tr><tr><td><code>RemoteApiSyncException</code></td><td>Record not found, missing remote id, incomplete pagination, rate limit exceeded</td></tr></tbody></table><p><code>RemoteApiSyncException::rateLimitExceeded()</code> sets <code>isRateLimit = true</code> and <code>retryAfterSeconds</code>.</p>',67),c=[d];function i(s,n,l,p,h,m){return o(),t("div",null,c)}const g=e(r,[["render",i]]);export{y as __pageData,g as default};
